<div class="admin-heading"><div><span>المحتوى والسيو</span><h1><?= $post?'تعديل المقال':'إضافة مقال جديد' ?></h1></div><a href="/admin/posts">رجوع</a></div><form class="editor-grid" method="post" action="<?= $post?'/admin/posts/'.(int)$post['id'].'/update':'/admin/posts' ?>"><?= csrf_field() ?><section class="panel form-panel"><label>عنوان المقال<input name="title" value="<?= e($post['title']??'') ?>" required></label><label>الرابط Slug<input name="slug" dir="ltr" value="<?= e($post['slug']??'') ?>" placeholder="يُنشأ تلقائيًا عند تركه فارغًا"></label><label>المقتطف<textarea name="excerpt" rows="3"><?= e($post['excerpt']??'') ?></textarea></label><label>المحتوى <small>يدعم HTML المنسق</small><textarea name="content" rows="18" dir="rtl"><?= e($post['content']??'') ?></textarea></label></section><aside class="editor-side"><section class="panel form-panel"><label>الحالة<select name="status"><option value="draft" <?= ($post['status']??'')==='draft'?'selected':'' ?>>مسودة</option><option value="published" <?= ($post['status']??'')==='published'?'selected':'' ?>>منشور</option></select></label><label>رابط الصورة الرئيسية<input name="featured_image" dir="ltr" value="<?= e($post['featured_image']??'') ?>"></label><button class="admin-btn" type="submit">حفظ المقال</button></section><section class="panel form-panel"><h3>SEO</h3><label>Meta Title<input name="meta_title" value="<?= e($post['meta_title']??'') ?>" maxlength="255"></label><label>Meta Description<textarea name="meta_description" rows="4" maxlength="320"><?= e($post['meta_description']??'') ?></textarea></label><label>Canonical URL<input name="canonical_url" dir="ltr" value="<?= e($post['canonical_url']??'') ?>"></label></section></aside></form>